$pw=ConvertTo-SecureString "NewSecureP@ssw0rd2025!" -AsPlainText -Force;$c=New-Object PSCredential("root",$pw);Get-SSHSession|Remove-SSHSession 2>$null|Out-Null;$s=New-SSHSession -ComputerName 72.62.35.177 -Credential $c -AcceptKey -Force 2>$null;if($s){$p=Invoke-SSHCommand -SessionId $s.SessionId -Command "cat /var/www/alqaed-api/.env|grep DB_PASSWORD|cut -d'=' -f2";$dbpw=$p.Output.Trim();Write-Host "DB Pass: $dbpw";$r=Invoke-SSHCommand -SessionId $s.SessionId -Command "mysql -u root -p'$dbpw' Freelance -e 'CREATE TABLE IF NOT EXISTS message_deletions(id INT AUTO_INCREMENT PRIMARY KEY,message_id INT NOT NULL,user_id VARCHAR(36)NOT NULL,deleted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_message_user(message_id,user_id),FOREIGN KEY(message_id)REFERENCES messages(id)ON DELETE CASCADE);SHOW TABLES;'";Write-Host $r.Output;if($r.Output -match "message_deletions"){Write-Host "SUCCESS!" -ForegroundColor Green;$pm2=Invoke-SSHCommand -SessionId $s.SessionId -Command "pm2 restart alqaed-api";Write-Host $pm2.Output;Write-Host "DONE! Test website" -ForegroundColor Green}else{Write-Host "Failed: $($r.Output)" -ForegroundColor Red};Remove-SSHSession -SessionId $s.SessionId|Out-Null}
